	&DefaultButton;





function dir$dmpostvt(p){
	this.constructor(p);
	document._dir = p;
}

dir$dmpostvt.prototype = new DirEvent();

dir$dmpostvt.prototype.afterInit = function(renderType){
	var p = this._dir;			
	var grid = p.grid(0).data.obj.Rows;
	dir$dmpostvtHiddenNhomHTMaKho(p);
	dir$dmpostvtHiddenNhomHTMaLo(p);
	dir$dmpostvtLoadDataVT(p);

	const action = p.options.action;


	// Chỉ định các phần tử DOM vào biến để dễ sử dụng
	const deleteBtns = document.querySelectorAll('.delete-btn');
	const deleteVideoBtns = document.querySelectorAll('.delete-video-btn');
	const imagePicker = document.getElementById('imagePicker');
	const videoPicker = document.getElementById('videoPicker');
	const imageUploadArea = document.getElementById('imageUploadArea');
	const addVideoLabel = document.getElementById('addVideoLabel');
	const mainVideoPreview = document.getElementById('mainVideoPreview');

	const imageList = document.getElementById('imageList');
	const addLabel = document.getElementById('addImageLabel');
	const countSpan = document.getElementById('imageCount');
	const mainImagePreview = document.getElementById('mainImagePreview'); // 👉 lấy phần preview ảnh chính
	const refId = document.getElementById('refId').value;
	const maxImages = 9;
	let uploadedImages = []; // chỉ 9 ảnh
	let uploadedVideo = null; // chỉ 1 video														

	// Hàm để ẩn/hiện các phần tử, tắt input file và thêm/loại bỏ class 'view-mode'
	function toggleElements(displayStyle, isDisabled) {
		// Ẩn/hiện các nút xoá ảnh và video
		deleteBtns.forEach(btn => btn.style.setProperty('display', displayStyle, 'important'));
		deleteVideoBtns.forEach(btn => btn.style.setProperty('display', displayStyle, 'important'));

		// Tắt/bật input file
		if (isDisabled) {
			imagePicker.setAttribute('disabled', 'true');  // Vô hiệu hóa input
			videoPicker.setAttribute('disabled', 'true');  // Vô hiệu hóa input
		} else {
			imagePicker.removeAttribute('disabled');  // Bật lại input
			videoPicker.removeAttribute('disabled');  // Bật lại input
		}

		// Thêm/loại bỏ lớp 'view-mode'
		const action = isDisabled ? 'add' : 'remove';
		imageUploadArea?.classList[action]('view-mode');
		mainImagePreview?.classList[action]('view-mode');
		addVideoLabel?.classList[action]('view-mode');
		mainVideoPreview?.classList[action]('view-mode');
	}

	// Hàm để kiểm tra và cập nhật các thuộc tính CSS
	function updateStyles() {
		// Kiểm tra .main-image-preview có chứa ảnh <img> hay không
		if ($('.main-image-preview').find('img').length === 0) {
			$('.main-image-preview').css('border', '2px dashed #999');
		} else {
			$('.main-image-preview').css('border', '1px solid #ddd');
		}

		// Kiểm tra .image-wrapper không rỗng và thêm margin-right
		$('.image-grid .image-wrapper').each(function() {
			if ($(this).children().length > 0) {
				$(this).css('margin-right', '8px');
			} else {
				$(this).css('margin-right', '0');
			}
		});
	}

	// Gọi hàm kiểm tra và cập nhật ngay khi trang tải
	updateStyles();

	function updateImageCount() {
		countSpan.innerText = `(${uploadedImages.length}/${maxImages})`;
		addLabel.style.display = uploadedImages.length >= maxImages ? 'none' : 'flex';
	}

	function generateUniqueId() {
		return crypto.randomUUID?.() || `${Date.now()}-${Math.random()}`;
	}

	function updateMainImagePreview() {
		if (uploadedImages.length === 0) {
			mainImagePreview.innerHTML = 'Chưa có ảnh';
			mainImagePreview.style.backgroundImage = '';
		} else {
			const firstImg = uploadedImages[0];
			const srcSet = firstImg.detailMainSrcSet;
			const imgTag = document.createElement('img');
			imgTag.src = firstImg.productCardUrl || firstImg.url;
			if (srcSet) imgTag.srcset = srcSet;

			mainImagePreview.innerHTML = '';
			mainImagePreview.appendChild(imgTag);
		}
	}

	function renderImages() {
		imageList.innerHTML = '';
		uploadedImages.forEach(img => {
			const item = createImageItem(img);
			imageList.appendChild(item);
		});
		updateMainImagePreview();
	}

	imagePicker.addEventListener('change', async () => {
		if (action === 'VIEW') return;

		const files = Array.from(imagePicker.files);
		const remain = maxImages - uploadedImages.length;
		if (remain <= 0 || files.length === 0) return;

		const filesToUpload = files.slice(0, remain);
		const formData = new FormData();
		formData.append('refId', refId);
		filesToUpload.forEach(file => formData.append('files', file));

		try {
			const res = await fetch('http://localhost:5034/api/upload/multiple', {
				method: 'POST',
				body: formData
			});

			if (!res.ok) {
				const errMsg = await res.text(); // hoặc res.json() nếu bạn trả lỗi dưới dạng object
				$.showToast(`Lỗi upload: ${errMsg}`);
				return;
			}

			const result = await res.json();

			for (const img of result) {
				if (!img.id) img.id = generateUniqueId();
				uploadedImages.push(img);

				const isFirstImage = uploadedImages.length === 1; // Nếu là ảnh đầu tiên sau khi push

				const dataRow = [
					img.id,                   // media_id
					img.ext,                  // ext
					img.url,                  // url
					img.thumbnailUrl,         // thumbnail_url
					img.productCardUrl,       // product_card_url
					img.detailThumbSrcSet,    // detail_thumb_srcset
					img.detailMainSrcSet,     // detail_main_srcset
					img.videoUrl,             // video_url
					img.width,                // width
					img.height,               // height
					'image',                  // type
					isFirstImage ? 1 : 0,     // ✅ chỉ set is_cover = 1 nếu là ảnh đầu tiên
					1                        // status
				];

				if (typeof p !== 'undefined') {
					p.addRow(dataRow, 0);
				}
			}

			renderImages();
			updateImageCount();
			imagePicker.value = '';

			updateStyles();
		} catch (error) {
			console.error('Upload error:', error);
			$.showToast('Upload error:', error);
		}
	});

	imageList.addEventListener('click', async (e) => {
		if (action === 'VIEW') return;

		const target = e.target;
		if (!target.classList.contains('delete-btn')) return;

		const id = target.dataset.id;
		if (!id) return;

		// ❗Tìm đúng dòng trong bảng
		const rowIndex = p.grid(0).data.obj.Rows.findIndex(r => r[0] === id); // media_id ở vị trí index 0

		// ❗Xử lý xoá ảnh: gọi API luôn (cả NEW/EDIT)
		try {
			await fetch(`http://localhost:5034/file/${id}`, { method: 'DELETE' });
		} catch (err) {
			console.warn('Không thể xoá server:', err);
			$.showToast('Không thể xoá server:', err);
		}

		// Gỡ dòng khỏi bảng luôn
		if (rowIndex !== -1) p.deleteRow(rowIndex, 0);

		// Gỡ ảnh khỏi danh sách hiển thị
		uploadedImages = uploadedImages.filter(x => x.id !== id);
		renderImages();
		updateImageCount();
		updateStyles();
	});

	function createImageItem(img) {
		const wrap = document.createElement('div');
		wrap.className = 'image-wrapper';
		wrap.style.cssText = '';

		const image = document.createElement('img');
		image.src = img.thumbnailUrl || img.url;
		if (img.detailThumbSrcSet) image.srcset = img.detailThumbSrcSet;
		image.title = img.url;
		image.style.cssText = '';

		const removeBtn = document.createElement('button');
		removeBtn.innerText = '❌';
		removeBtn.className = 'delete-btn';
		removeBtn.dataset.id = img.id;
		removeBtn.style.cssText = '';

		wrap.appendChild(image);
		wrap.appendChild(removeBtn);
		return wrap;
	}

	function updateVideoUI() {
		if (uploadedVideo) {
			addVideoLabel.style.display = 'none';
			mainVideoPreview.style.display = 'flex';

			mainVideoPreview.innerHTML = `
				<div class="video-thumbnail-wrapper" style="position: relative; width: 100%; height: 100%;">
					<img src="${uploadedVideo.thumbnailUrl}" alt="Video thumbnail"
						style="width: 100%; height: 100%; object-fit: cover; border-radius: 6px;">

					<!-- Icon Play ở giữa -->
					<div style="
						position: absolute;
						inset: 0;
						display: flex;
						align-items: center;
						justify-content: center;
					">
						<div style="
							width: 32px;
							height: 32px;
							background: rgba(0, 0, 0, 0.7);
							border-radius: 50%;
							display: flex;
							align-items: center;
							justify-content: center;
							color: white;
						">
							▶
						</div>
					</div>

					<!-- Thời lượng video -->
					<div id="videoDurationOverlay" style="
						position: absolute;
						bottom: 4px;
						right: 4px;
						background: rgba(0, 0, 0, 0.7);
						color: #fff;
						padding: 2px 6px;
						font-size: 12px;
						border-radius: 3px;
					">--:--</div>

					<!-- Nút xóa -->
					<button class="delete-video-btn" data-id="${uploadedVideo.id}" style="
						position:absolute;
						top:4px;
						right:4px;
						width:20px;
						height:20px;
						background:red;
						color:white;
						border:none;
						border-radius:50%;
						cursor:pointer;
						font-size:14px;
					">❌</button>
				</div>
			`;

			// Dùng video ẩn để lấy thời lượng
			const hiddenVideo = document.createElement('video');
			hiddenVideo.src = uploadedVideo.url;
			hiddenVideo.preload = 'metadata';
			hiddenVideo.muted = true;
			hiddenVideo.playsInline = true;
			hiddenVideo.style.display = 'none';

			document.body.appendChild(hiddenVideo);
			hiddenVideo.addEventListener('loadedmetadata', () => {
				const duration = hiddenVideo.duration;
				const minutes = Math.floor(duration / 60);
				const seconds = Math.floor(duration % 60).toString().padStart(2, '0');
				document.getElementById('videoDurationOverlay').textContent = `${minutes}:${seconds}`;
				document.body.removeChild(hiddenVideo);
			});
		} else {
			addVideoLabel.style.display = 'flex';
			mainVideoPreview.style.display = 'none';
			mainVideoPreview.innerHTML = '';
		}
	}

	updateVideoUI();

	videoPicker.addEventListener('change', async () => {
		if (action === 'VIEW') return;

		const file = videoPicker.files?.[0];
		if (!file || uploadedVideo) return;

		const formData = new FormData();
		formData.append('refId', refId);
		formData.append('files', file);

		try {
			const res = await fetch('http://localhost:5034/api/upload/multiple', {
				method: 'POST',
				body: formData
			});

			if (!res.ok) {
				const errMsg = await res.text(); // hoặc res.json() nếu bạn trả lỗi dưới dạng object
				$.showToast(`Lỗi upload: ${errMsg}`);
				return;
			}

			const result = await res.json();
			const video = result.find(f => f.url?.endsWith('.mp4'));

			if (video) {
				// 🟢 Tạo dataRow để add vào bảng
				const dataRow = [
					video.id,                   // media_id
					video.ext,                  // ext
					video.url,                  // url
					video.thumbnailUrl,         // thumbnail_url
					video.productCardUrl,       // product_card_url
					video.detailThumbSrcSet,    // detail_thumb_srcset
					video.detailMainSrcSet,     // detail_main_srcset
					video.videoUrl,             // video_url
					video.width,                // width
					video.height,               // height
					'video',                  // type
					0,                        // is_cover
					1                       // status                   
				];

				// 🔁 Add vào bảng
				if (typeof p !== 'undefined') {
					p.addRow(dataRow, 0);
				}

				uploadedVideo = video;
				updateVideoUI();
			}

			videoPicker.value = '';
		} catch (err) {
			console.error('Lỗi upload video:', err);
			$.showToast('Lỗi upload video:', err);															
		}
	});

	// 👇 Sự kiện xoá video
	mainVideoPreview.addEventListener('click', async (e) => {
		if (action === 'VIEW') return;

		if (e.target.classList.contains('delete-video-btn')) {
			const id = e.target.dataset.id;
			if (!id) return;

			// Tìm đúng dòng trong bảng
			const rowIndex = p.grid(0).data.obj.Rows.findIndex(r => r[0] === id);

			// Gọi API xoá video ngay lập tức (NEW/EDIT đều vậy)
			try {
				await fetch(`http://localhost:5034/file/${id}`, { method: 'DELETE' });
			} catch (err) {
				console.warn('Không thể xoá video:', err);
				$.showToast('Không thể xoá video:', err);
			}

			if (rowIndex !== -1) p.deleteRow(rowIndex, 0);

			uploadedVideo = null;
			updateVideoUI();
		}
	});

	// Kiểm tra điều kiện action và mavt
	if (action === 'VIEW' || p.valForm('ma_vt') === '') {
		// Ẩn các nút xoá ảnh và video, tắt input file và thêm class view-mode
		toggleElements('none', true);
	} else {
		console.log("Không phải chế độ VIEW và mavt có giá trị");
		// Các thao tác khi không phải 'VIEW' hoặc mavt có giá trị, nếu có cần thực hiện gì đó, có thể thêm logic ở đây
		toggleElements('block', false);
	}

	if (action === 'EDIT' || action === 'VIEW') {
		const rows = p.grid(0).data.obj.Rows;
		uploadedImages = [];
		uploadedVideo = null;

		rows.forEach(row => {
			const [
				mediaIdValue, extValue, urlValue, thumbnailUrlValue, productCardUrlValue,
				detailThumbSrcsetValue, detailMainSrcsetValue, videoUrlValue,
				widthValue, heightValue, typeValue, isCoverValue, statusValue, mavtValue, lineValue
			] = row;

			const media = {
				refId: mavtValue,
				id: mediaIdValue,
				ext: extValue,
				url: urlValue,
				thumbnailUrl: thumbnailUrlValue,
				productCardUrl: productCardUrlValue,
				detailThumbSrcSet: detailThumbSrcsetValue,
				detailMainSrcSet: detailMainSrcsetValue,
				videoUrl: videoUrlValue,
				width: widthValue,
				height: heightValue,
				type: typeValue,
				isCover: isCoverValue === 1 || isCoverValue === true
			};

			if (typeValue === 'image') {
				uploadedImages.push(media);
			} else if (typeValue === 'video') {
				uploadedVideo = media;
			}
		});

		// Cập nhật giao diện
		renderImages();
		updateMainImagePreview();
		updateVideoUI();
		updateImageCount();
		updateStyles();
	}

	var mota = document.querySelector('input.mo_ta')
	editor_mota = CKEDITOR.replace(mota, {
		customConfig: '/ckeditor/config.js',
		extraAllowedContent: 'span',
		maxLength: 256, 
	});	
	editor_mota.setData(document.querySelector('input.mo_ta').value);
	editor_mota.on('change', function () {
		document.querySelector('input.mo_ta').value = editor_mota.getData();
	});		
}

// Sửa lại beforeButtonDialogClick (chỉ giữ lại case 'ok' trống):
dir$dmpostvt.prototype.beforeButtonDialogClick = async function (id) {
    // Nếu có logic khác thì giữ lại, KHÔNG xử lý xóa ảnh/video nữa
    return true;
}			

dir$dmpostvt.prototype.formFieldValueChange = function (o, cF, v) {
	var p = this._dir;
	switch (cF){
		case 'ma_kho':
		  p.valForm(['ma_vi_tri', 'ten_vi_tri'], ['', '']);
		  dir$dmpostvtHiddenNhomHTMaKho(p);
		break;
		case 'ma_lo':
		  dir$dmpostvtHiddenNhomHTMaLo(p);
		break;
		case 'ma_vt':
			dir$dmpostvtLoadDataVT(p);

			// Chỉ định các phần tử DOM vào biến để dễ sử dụng
			const deleteBtns = document.querySelectorAll('.delete-btn');
			const deleteVideoBtns = document.querySelectorAll('.delete-video-btn');
			const imagePicker = document.getElementById('imagePicker');
			const videoPicker = document.getElementById('videoPicker');
			const imageUploadArea = document.getElementById('imageUploadArea');
			const mainImagePreview = document.getElementById('mainImagePreview');
			const addVideoLabel = document.getElementById('addVideoLabel');
			const mainVideoPreview = document.getElementById('mainVideoPreview');

			// Hàm giúp ẩn/hiện các nút xoá
			function toggleDeleteBtns(displayStyle) {
				deleteBtns.forEach(btn => btn.style.setProperty('display', displayStyle, 'important'));
				deleteVideoBtns.forEach(btn => btn.style.setProperty('display', displayStyle, 'important'));
			}

			// Hàm bật/tắt input file
			function toggleFileInput(disabled) {
				// Tắt/bật input file
				if (disabled) {
					imagePicker.setAttribute('disabled', 'true');  // Vô hiệu hóa input
					videoPicker.setAttribute('disabled', 'true');  // Vô hiệu hóa input
				} else {
					imagePicker.removeAttribute('disabled');  // Bật lại input
					videoPicker.removeAttribute('disabled');  // Bật lại input
				}
			}

			// Hàm xử lý các phần tử có lớp 'view-mode'
			function toggleViewMode(isViewMode) {
				const action = isViewMode ? 'add' : 'remove';
				imageUploadArea?.classList[action]('view-mode');
				mainImagePreview?.classList[action]('view-mode');
				addVideoLabel?.classList[action]('view-mode');
				mainVideoPreview?.classList[action]('view-mode');
			}

			// Kiểm tra nếu v không phải là rỗng
			if (v !== '') {
				console.log(v);

				// Hiện nút xoá ảnh và video
				toggleDeleteBtns('block');

				// Bật input file
				toggleFileInput(false);

				// Hiển thị các vùng tải ảnh/video
				toggleViewMode(false);
			} else {
				console.log(v);

				// Ẩn nút xoá ảnh và video
				toggleDeleteBtns('none');

				// Tắt input file
				toggleFileInput(true);

				// Ẩn các vùng tải ảnh/video
				toggleViewMode(true);
			}

			break;
		default:
			break;
	}
}
function dir$dmpostvtLoadDataVT(p){
	var maVT = p.valForm('ma_vt');

	if (p.options.action == "NEW")
	{
		p.request('request_dmvt', '', [['ma_vt', 'C', maVT]], function(pp, d, run){
			if (run) {
				console.log('Load du lieu thanh cong');
			}
		});
	}
	else {
		p.setDisabled('ma_vt', true);
	}				  
}
function dir$dmpostvtHiddenNhomHTMaKho(p){
	var  maKho = p.valForm('ma_kho');

	if (maKho) {
	  p.find(".control-label.ma_htnhom1, .input-field.ma_htnhom1").css("display", "block");
	}
	else p.find(".control-label.ma_htnhom1, .input-field.ma_htnhom1").css("display", "none");
}
function dir$dmpostvtHiddenNhomHTMaLo(p){
	var  maLot = p.valForm('ma_lo');

	if (maLot) {
	  p.find(".control-label.ma_htnhom2, .input-field.ma_htnhom2").css("display", "block");
	}
	else p.find(".control-label.ma_htnhom2, .input-field.ma_htnhom2").css("display", "none");
}







				.preview { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 10px; }
				.preview img, .preview video {
					width: 150px; height: 150px; object-fit: cover; border: 1px solid #ccc; border-radius: 6px;
				}
				input[type="file"] { margin-bottom: 10px; }
				.image-wrapper {
					position: relative;
					width: 120px;
					height: 120px;
					border: 1px solid #ccc;
					border-radius: 4px;
					overflow: hidden;
					background: #fff;
				}

				.uploaded-image {
					width: 100%;
					height: 100%;
					object-fit: cover;
				}

				.remove-button {
					position: absolute;
					top: 2px;
					right: 2px;
					background: rgba(255, 0, 0, 0.8);
					color: #fff;
					border: none;
					border-radius: 50%;
					width: 20px;
					height: 20px;
					font-size: 12px;
					cursor: pointer;
				}

				.main-radio {
					position: absolute;
					bottom: 4px;
					left: 4px;
					cursor: pointer;
				}

				.main-preview {
					min-width: 80px;
					width: 80px;
					max-width: 80px;
					height: 80px;
					display: flex;
					align-items: center;
					justify-content: center;
					font-size: 12px;
					color: #666;
					background-color: #fafafa;
					border-radius: 8px;
					background-size: cover;
					background-position: center;
					background-repeat: no-repeat;
					border: 2px dashed #999;
				}

				.main-preview img {
					width: 100%;
					height: 100%;
					object-fit: contain;
					border-radius: 8px;
				}

				.main-video-preview {
					position: relative;
				}

				.image-grid {
					display: flex;
					gap: 8px;
					overflow-x: auto;
					padding: 4px 0 4px 0;
				}

				/* Mỗi ảnh sản phẩm */
				.image-wrapper {
					position: relative;
					width: 80px;
					height: 80px;
					border-radius: 6px;
					border: 1px solid #ddd;
					overflow: hidden;
					background-color: #f8f8f8;
					flex-shrink: 0;
				}

				/* Ảnh bên trong */
				.image-wrapper img {
					width: 100%;
					height: 100%;
					object-fit: contain;
					display: block;
				}

				/* Nút xóa ❌ */
				.delete-btn {
					position: absolute;
					top: 4px;
					right: 4px;
					width: 20px;
					height: 20px;
					background: rgba(255, 0, 0, 0.8);
					color: white;
					border: none;
					border-radius: 50%;
					cursor: pointer;
					font-size: 14px;
					line-height: 20px;
					text-align: center;
				}

