					DECLARE @ten_vt NVARCHAR(256), @ten_vt2 NVARCHAR(256), @dvt VARCHAR(32), @ma_kho VARCHAR(32), @ten_kho NVARCHAR(256), @ma_lo VARCHAR(32), @ten_lo NVARCHAR(256)

					IF 1 = (SELECT COUNT(1) FROM dmvt WHERE ma_vt = @ma_vt) BEGIN
						SELECT @ten_vt = a.ten_vt, @ten_vt2 = a.ten_vt2, @dvt = a.dvt, @ma_kho = a.ma_kho, @ten_kho = b.ten_kho, @ma_lo = a.ma_lo, @ten_lo = c.ten_lo
						FROM dmvt a
							LEFT JOIN dmkho b on a.ma_kho = b.ma_kho
							LEFT JOIN dmlo c on a.ma_lo = c.ma_lo
						WHERE a.ma_vt = @ma_vt
					END

					SELECT ISNULL(@ten_vt, '') [!ten_vt], ISNULL(@ten_vt2, '') [!ten_vt2], ISNULL(@dvt, '') [!dvt], ISNULL(@ma_kho, '') [!ma_kho], ISNULL(@ten_kho, '') [!ten_kho], ISNULL(@ma_lo, '') [!ma_lo], ISNULL(@ten_lo,'') [!ten_lo]







					select @@fields into #@@table from @@table a where [%whereFieldKey]
					[%updateRef]
					select * from #@@table

					declare @script nvarchar(4000)
					if @script is null set @script = ''

					if @action = 'EDIT'
					  if exists(select 1 from syscodeexists with(nolock, index(code1)) where code1 = @ma_vt and field = 'ma_vt')
						select @script = @script + 'p.setDisabled(''ma_vt'', false); '

					if @action in ('EDIT', 'VIEW') select @script as script
					drop table #@@table







					IF @ma_lvtc1 <> '' AND EXISTS (SELECT 1 FROM dmlvtc2 WHERE ma_lvtc1 = @ma_lvtc1) AND (@ma_lvtc2 IS NULL OR @ma_lvtc2 = '')
					BEGIN
						SELECT '$EmptyLvtc2' as message, 'ma_lvtc2' as field
						RETURN;
					END

					IF @ma_lvtc2 <> '' AND EXISTS (SELECT 1 FROM dmlvtc3 WHERE ma_lvtc2 = @ma_lvtc2) AND (@ma_lvtc3 IS NULL OR @ma_lvtc3 = '')
					BEGIN

						SELECT '$EmptyLvtc3' as message, 'ma_lvtc3' as field
						RETURN;
					END

					IF @ma_lvtc3 <> '' AND EXISTS (SELECT 1 FROM dmlvtc4 WHERE ma_lvtc3 = @ma_lvtc3) AND (@ma_lvtc4 IS NULL OR @ma_lvtc4 = '')
					BEGIN

						SELECT '$EmptyLvtc4' as message, 'ma_lvtc4' as field
						RETURN;
					END

					IF @ma_lvtc4 <> '' AND EXISTS (SELECT 1 FROM dmlvt WHERE ma_lvtc4 = @ma_lvtc4) AND (@ma_lvt IS NULL OR @ma_lvt = '')
					BEGIN

						SELECT '$EmptyLvtc5' as message, 'ma_lvtc5' as field
						RETURN;
					END






					select 'p.options._files = null;' as script







					if exists(select 1 from syscodeexists with(nolock, index(code1)) where code1 = @ma_vt and field = 'ma_vt') begin
						select '$ListItemUsed' as message
						return
					end







